/**
 * FROZEN — deck-v2
 *
 * deck-v2 keeps the deck-v1 deck and shuffle untouched and only changes how
 * the shuffle seed is derived: player entropy is folded in through HMAC.
 *
 *   shuffleSeed = HMAC-SHA256(key = serverSeed, message = "<clientSeed>:<nonce>")
 *
 * The client seed is the combination of the seated players' own seeds (see
 * client-seed.ts); the nonce is the table-level hand counter. The separator is
 * part of the frozen format: it keeps ("ab", 12) and ("a", "b12") distinct.
 *
 * DO NOT EDIT THIS FILE. A different derivation requires deck-v3 (and a new
 * algorithm id) so that historical hands stay verifiable.
 */

import { hmacSha256Hex, sha256Hex } from './sha256.js';
import { deckStringV1, makeDeckV1, shuffleDeckV1, type FairCard } from './deck-core.js';

export const DECK_V2_ALGORITHM = 'deck-v2';

export function deckV2SeedMessage(clientSeed: string, nonce: number): string {
  return `${clientSeed}:${nonce}`;
}

/** The exact string handed to the engine's shuffleDeck for a deck-v2 hand. */
export async function shuffleSeedV2(
  serverSeed: string,
  clientSeed: string,
  nonce: number,
): Promise<string> {
  return hmacSha256Hex(serverSeed, deckV2SeedMessage(clientSeed, nonce));
}

export async function deckFromSeedV2(
  serverSeed: string,
  clientSeed: string,
  nonce: number,
): Promise<FairCard[]> {
  return shuffleDeckV1(makeDeckV1(), await shuffleSeedV2(serverSeed, clientSeed, nonce));
}

export async function deckHashV2(
  serverSeed: string,
  clientSeed: string,
  nonce: number,
): Promise<string> {
  return sha256Hex(deckStringV1(await deckFromSeedV2(serverSeed, clientSeed, nonce)));
}
